use serde_json::Value;

fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut result = String::new();
    for c in input.as_str() {
        if c.is_alphabetic() {
            let offset = if c.is_uppercase() { 65 } else { 97 };
            let new_char = ((c as u8 + 13) % 26) as u8 + offset;
            result.push((new_char as char).to_string());
        } else {
            result.push(c);
        }
    }
    result
}

fn main() {
    let input = serde_json::Value::from("{\"input\":\"Hello, Z!\",\"expected\":\"Uryyb, M!"}");
    let output = solve(input);
    println!("{:?}", output);
}
```

